int fun1 (int n) {
     int i, j, k, p, q = 0;
     for (i = 1; i < n; ++i)    // O(n)
     {
        p = 0;
       for (j = n; j > 1; j = j/2)     // O(logn)
           ++p; 
       for (k = 1; k < p; k = k * 2)     // O(logp) = O(loglogn)
           ++q;
     }
     return q;
}

